P0 = (36.8528, 10.3237)
KX, KY = 111320.0 * math.cos(math.radians(36.853)), 110950.0


def UV(u, v):
    """(lat, lon) on the Roman street grid, as in geo.py."""
    e = 0.8660254 * u + 0.5 * v
    n = -0.5 * u + 0.8660254 * v
    return (round(P0[0] + n / KY, 5), round(P0[1] + e / KX, 5))


